{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Disopyramide, which shares the phenyl/pyridyl and basic amine features with the query, has an absolute oral bioavailability of 73% in human subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Doxylamine, a close phenyl/pyridyl tertiary-carbinol analogue, has an oral bioavailability of 50% in normal subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Imidafenacin, a structurally related basic drug with aromatic substituents, has an absolute oral bioavailability of 57.8% in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Fexofenadine, which shares the piperidine and diphenyl-carbinol motif, has an absolute oral bioavailability of 41 ± 8.5% in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Ebastine, a lipophilic piperidine-containing antihistamine, achieves about 40% oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Bepotastine, a pyridyl-piperidine drug, shows high oral bioavailability of >80% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Terfenadine has very low absolute oral bioavailability (<5%) in humans, but this is largely due to extensive first-pass metabolism as a prodrug to fexofenadine, a specific liability not clearly present in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "The (R)-enantiomer of oxybutynin has an estimated oral bioavailability of about 6.7%, but this low value is associated with ester-containing structure and extensive first-pass metabolism, making it less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic basic tertiary amine with a 2,6-dimethylpiperidine and a phenyl/pyridyl carbinol. The closest experimental analogues (disopyramide, doxylamine, imidafenacin) show absolute oral bioavailability of 50-90%, and other related drugs (fexofenadine, ebastine, bepotastine) are also ≥30-80%. The low-F analogues (terfenadine, oxybutynin) are less similar and have specific first-pass metabolic liabilities not present in the query. Therefore, F ≥20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for the query molecule.",
    "Metabolic stability and first-pass metabolism of the query are unknown; CYP3A4/P-gp liabilities cannot be excluded.",
    "Morgan similarities to the evidence molecules are low (<0.35), limiting quantitative transferability.",
    "The absence of terfenadine-like prodrug metabolism and oxybutynin-like ester liability in the query is inferred from structure, not experimentally confirmed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

